import { useEffect, useMemo, useRef, useState } from 'react';
import { SPEED_SECONDS, SPEED_UNTIMED_QUESTIONS, buildSpeedQuestions, seededRng } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { ModeScreen, ModeSummary, NoTimer } from '../ModeScreen.js';
import type { ModeProps } from '../ModeRoute.js';
import { saveModePrefs } from '../data.js';
import { missedWords, useModeRun } from '../useModeRun.js';
import { useClock } from '../useClock.js';
import styles from '../Modes.module.css';

/**
 * More questions than anybody answers in a timed round, so the round ends
 * on the clock and never on an empty list. Each word is asked once before
 * any is asked again.
 */
const TIMED_QUESTIONS = 200;
/** How long a right answer stays marked before the next question. */
const RIGHT_SHOWN_MS = 260;
/** How long a wrong answer stays, with the right one shown. */
const WRONG_SHOWN_MS = 900;
/** The clock turns red for the last seconds. */
const LOW_SECONDS = 10;

type Phase = 'ready' | 'running' | 'done';

/**
 * Speed round: as many of the learner's own meanings as they can match to
 * the word in a minute, four choices each. "No timer" asks a fixed number
 * at their own pace instead. The best timed round per notebook is kept on
 * this device.
 *
 * Practice only (card type speed, source game): guessing against a clock is
 * not evidence of memory, so no box moves.
 */
export function Speed({ view, lang, meaningLang }: ModeProps): React.JSX.Element {
  const run = useModeRun('speed');
  const [phase, setPhase] = useState<Phase>('ready');
  const noTimer = view.prefs.noTimer;
  // Fixed when a round starts: the switch can change between rounds, not during one.
  const [timed, setTimed] = useState(!noTimer);
  // The best before this round, to tell a new best from an old one.
  const [bestBefore, setBestBefore] = useState<number | undefined>(undefined);
  const questions = useMemo(
    () =>
      buildSpeedQuestions(view.words, timed ? TIMED_QUESTIONS : SPEED_UNTIMED_QUESTIONS, seededRng(run.seed)),
    // A new list per run, not per answer (every answer changes the words' progress).
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [run.seed, timed],
  );
  const [index, setIndex] = useState(0);
  const [picked, setPicked] = useState<string | undefined>(undefined);
  const [said, setSaid] = useState('');
  const shownAt = useRef(0);
  const elapsed = useClock(phase === 'running' && timed, run.seed);
  const left = Math.max(0, SPEED_SECONDS - elapsed);
  const timeUp = phase === 'running' && timed && left === 0;
  const over = phase === 'done' || timeUp;
  // Read by the timers a question leaves behind, which can outlive the round.
  const overRef = useRef(false);
  const notebookId = view.notebook?.id ?? '';
  const right = run.answers.filter((answer) => answer.correct).length;
  const newBest = timed && right > 0 && (bestBefore === undefined || right > bestBefore);

  // The end of a timed round keeps a new best on this device.
  useEffect(() => {
    overRef.current = over;
    if (over && newBest) {
      void saveModePrefs((prefs) => ({ ...prefs, speedBest: { ...prefs.speedBest, [notebookId]: right } }));
    }
    // Once, when the round ends.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [over]);

  const question = questions[index];

  const choose = (optionId: string): void => {
    if (over || phase !== 'running' || question === undefined || picked !== undefined) return;
    setPicked(optionId);
    const correct = optionId === question.id;
    const answer = question.options.find((option) => option.id === question.id);
    setSaid(correct ? t('session.correct') : t('modes.speedWrong', { word: answer?.label ?? '' }));
    void run.record({
      wordId: question.id,
      headword: answer?.label ?? '',
      correct,
      latencyMs: Date.now() - shownAt.current,
      ...(correct ? {} : { pickedWordId: optionId }),
    });
    window.setTimeout(
      () => {
        if (overRef.current) return;
        setPicked(undefined);
        shownAt.current = Date.now();
        if (index + 1 >= questions.length) setPhase('done');
        else setIndex(index + 1);
      },
      correct ? RIGHT_SHOWN_MS : WRONG_SHOWN_MS,
    );
  };

  // Keys 1 to 4 pick, as in a session.
  useEffect(() => {
    if (phase !== 'running' || over) return undefined;
    const onKey = (event: KeyboardEvent): void => {
      const n = Number(event.key);
      if (!Number.isInteger(n) || n < 1 || n > 4 || event.metaKey || event.ctrlKey || event.altKey) return;
      const option = question?.options[n - 1];
      if (option !== undefined) choose(option.id);
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  });

  const start = (): void => {
    setTimed(!noTimer);
    setBestBefore(view.prefs.speedBest[notebookId]);
    run.restart();
    setIndex(0);
    setPicked(undefined);
    setSaid('');
    overRef.current = false;
    shownAt.current = Date.now();
    setPhase('running');
  };

  if (over) {
    return (
      <ModeSummary
        title={t('modes.speed')}
        lang={lang}
        score={t('modes.speedScore', { count: right })}
        lines={[
          ...(timeUp ? [t('modes.timeUp')] : []),
          t('modes.scoreOf', { right, total: run.answers.length }),
        ]}
        best={!timed ? undefined : newBest ? 'new' : bestBefore}
        missed={missedWords(run.answers)}
        onAgain={() => {
          setPhase('ready');
        }}
      />
    );
  }

  if (phase === 'ready') {
    const previous = view.prefs.speedBest[notebookId];
    return (
      <ModeScreen
        title={t('modes.speed')}
        counts={false}
        actions={
          <button type="button" className={styles.primary} onClick={start}>
            {t('modes.start')}
          </button>
        }
      >
        <div className={styles.ready}>
          <div className={styles.prompt}>
            <span className={styles.promptText}>
              {noTimer
                ? t('modes.speedReadyUntimed', { count: SPEED_UNTIMED_QUESTIONS })
                : t('modes.speedReady', { seconds: SPEED_SECONDS })}
            </span>
            {!noTimer && previous !== undefined && (
              <span className={styles.best}>{t('modes.best', { count: previous })}</span>
            )}
          </div>
          <NoTimer
            on={noTimer}
            onChange={(on) => {
              void saveModePrefs((prefs) => ({ ...prefs, noTimer: on }));
            }}
          />
        </div>
      </ModeScreen>
    );
  }

  return (
    <ModeScreen
      title={t('modes.speed')}
      ask={t('modes.speedAsk')}
      counts={false}
      progress={timed ? undefined : { done: index, total: questions.length }}
      timer={
        timed
          ? { seconds: left, label: t('modes.timeLeft', { count: left }), low: left <= LOW_SECONDS }
          : undefined
      }
      said={said}
    >
      {question !== undefined && (
        <>
          <div className={styles.prompt}>
            <span className={styles.promptText}>
              <Bilingual lang={meaningLang}>{question.meaning}</Bilingual>
            </span>
          </div>
          <div className={styles.options} role="group" aria-label={t('session.pickAnswer')}>
            {question.options.map((option, n) => {
              const isAnswer = option.id === question.id;
              const show = picked !== undefined && (isAnswer || option.id === picked);
              return (
                <button
                  key={option.id}
                  type="button"
                  className={cx(
                    styles.option,
                    show && isAnswer && styles.right,
                    show && !isAnswer && cx(styles.wrong, styles.shake),
                  )}
                  disabled={picked !== undefined}
                  onClick={() => {
                    choose(option.id);
                  }}
                >
                  <span className={styles.optionKey}>{n + 1}</span>
                  <span className={styles.optionLabel}>
                    <Bilingual lang={lang}>{option.label}</Bilingual>
                  </span>
                </button>
              );
            })}
          </div>
        </>
      )}
    </ModeScreen>
  );
}
